written = 0
for cid in ids:
    assert cid in P, cid
    rec = {"case_id": cid, "prediction_text": P[cid]['prediction_text'], "basis": P[cid]['basis'],
           "confidence": P[cid]['confidence'], "trigger": P[cid]['trigger']}
    (outdir/f"{cid}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding='utf-8')
    written += 1
assert written == len(ids) == 20, (written, len(ids))
# verify only this batch's files, by exact id list
cnt = sum(1 for cid in ids if (outdir/f"{cid}.json").exists())
assert cnt == 20
tc = {"changed_main":0,"reserve_used":0,"disputed":0}
for cid in ids:
    t = json.loads((outdir/f"{cid}.json").read_text())['trigger']
    for k in tc: tc[k] += bool(t[k])
print("written", written, "verified", cnt, "trigger_counts", tc)
